void *snd_usb_find_csint_desc(void *buffer, int buflen, void *after, u8 dsubtype) /* <=== snd_usb_find_csint_desc */ 
{
	unsigned char *p = after;

	while ((p = snd_usb_find_desc(buffer, buflen, p,
				      USB_DT_CS_INTERFACE)) != NULL) {
		if (p[0] >= 3 && p[2] == dsubtype)
			return p;
	}
	return NULL;
}

