static inline void set_bit(int nr, volatile unsigned long *addr) /* <=== set_bit */ 
{
	__op_bit(or, __NOP, nr, addr);
}

static inline int /* <=== test_bit */ 
test_bit(unsigned int nr, const volatile unsigned long *addr)
{
	unsigned long mask;

	addr += nr >> 5;

	mask = 1UL << (nr & 0x1f);

	return ((mask & *addr) != 0);
}

static inline void *kzalloc(size_t s, gfp_t gfp) /* <=== kzalloc */ 
{
